/* ============================================================
   أطياب الجاسم (React) — مشهد دهن العود ثلاثي الأبعاد (BukhoorScene)

   ملف المالك كما أُرسل حرفيًا (مشهد عود/بخور فاخر: نار + دخان +
   شرر + غبار، DPR متكيف، يتوقف خارج الشاشة) — يُعرض عبر غلاف
   OudOil3D الذي يضيف التحميل الكسول والنقر لصفحة العود.
   روابط النموذج والخلفية من رفع المالك (user.uploads.dev).
   ============================================================ */
import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';

/**
 * BukhoorScene — luxury oud/bukhoor 3D hero (black & gold set on marble).
 *
 * Lightweight by design for e-commerce sites:
 *  - Optimized model (~2.4MB: 60k tris, 1024px texture, baked normals)
 *  - 3 GPU particle systems (smoke / ember sparks / falling dust), zero per-frame CPU
 *  - 1 flickering point light, no shadows, no post-processing
 *  - DPR clamped (2 desktop / 1.6 mobile), auto-degrades to 1x on slow devices
 *  - Pauses when off-screen or tab hidden; honors prefers-reduced-motion
 *
 * npm:  npm i three
 *
 *   import BukhoorScene from './BukhoorScene.jsx';
 *   <BukhoorScene style={{ height: 520 }} effects autoRotate={false}
 *     onProgress={(p) => console.log(p)} onReady={() => console.log('ready')} />
 */

export const DEFAULT_MODEL_URL =
  'https://user.uploads.dev/file/6755d966426a7383edd6a5ff554354b4.glb';
/* ★ خلفية محلية مضغوطة (82KB WebP بدل 326KB JPG خارجي): نفس الصورة
   ضُغطت محلياً — توفير 238KB + كاش طويل + بلا اتصال طرف ثالث.
   الرابط الخارجي يبقى احتياطاً فقط إن فُقد الملف المحلي. */
export const LOCAL_BACKGROUND_URL =
  (typeof process !== "undefined" && process.env && process.env.PUBLIC_URL ? process.env.PUBLIC_URL : "") + "/home/oud-backdrop.webp";
export const DEFAULT_BACKGROUND_URL = LOCAL_BACKGROUND_URL ||
  'https://user.uploads.dev/file/9d69b34074569559393a70806cac8a41.jpg';
// Tiny blur placeholder (model texture, 32x18) shown behind the canvas while loading
export const DEFAULT_PLACEHOLDER =
  'data:image/jpeg;base64,';

const P = {
  modelScale: 1.0,
  modelRotY: 0.18,
  modelPos: [0.14, 0.254, 0],
  tipLocal: [0.01, 0.275, -0.2], // spoon tip (kept for reference; fire now lives in the jar)
  mouthLocal: [0.03, 0.105, 0.05], // jar mouth = fire source: flame + smoke + sparks + ember light
  discA: [0.05, 0.018, 0.305],
  discB: [0.2, 0.018, 0.305],
  camPos: [0.32, 0.72, 2.55],
  camLook: [0.05, 0.22, 0],
};

function softCircleTexture(size, hardness) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const x = c.getContext('2d');
  const g = x.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(hardness, 'rgba(255,255,255,.55)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  x.fillStyle = g;
  x.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function noiseTexture(size = 256) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const x = c.getContext('2d');
  const d = x.createImageData(size, size);
  for (let i = 0; i < d.data.length; i += 4) {
    const v = 150 + Math.random() * 90;
    d.data[i] = d.data[i + 1] = d.data[i + 2] = v;
    d.data[i + 3] = 255;
  }
  x.putImageData(d, 0, 0);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(3, 2);
  return t;
}

function shadowTexture() {
  const s = 256;
  const c = document.createElement('canvas');
  c.width = c.height = s;
  const x = c.getContext('2d');
  const g = x.createRadialGradient(s / 2, s / 2, s * 0.05, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(0,0,0,.62)');
  g.addColorStop(0.55, 'rgba(0,0,0,.30)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g;
  x.fillRect(0, 0, s, s);
  return new THREE.CanvasTexture(c);
}

// The scan's spoon area has pale patches; warm them to gold (multiplicative, feathered)
function patchSpoonGold(mat) {
  mat.onBeforeCompile = (sh) => {
    sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vSpoonLocal;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvSpoonLocal = position;');
    sh.fragmentShader = sh.fragmentShader
      .replace('#include <common>', '#include <common>\nvarying vec3 vSpoonLocal;')
      .replace(
        '#include <map_fragment>',
        `#include <map_fragment>
        {
          float mx = 1.0 - smoothstep(-0.06, 0.03, vSpoonLocal.x);
          float my = smoothstep(-0.10, 0.02, vSpoonLocal.y);
          float m = mx * my;
          float lum = dot(diffuseColor.rgb, vec3(0.299, 0.587, 0.114));
          float pale = smoothstep(0.22, 0.55, lum);
          diffuseColor.rgb *= mix(vec3(1.0), vec3(1.02, 0.76, 0.45), m * (0.35 + 0.65 * pale));
        }`
      );
  };
  mat.customProgramCacheKey = () => 'spoon-gold-v1';
}

export default function BukhoorScene({
  modelUrl = DEFAULT_MODEL_URL,
  backgroundUrl = DEFAULT_BACKGROUND_URL,
  placeholder = DEFAULT_PLACEHOLDER,
  effects = true,
  autoRotate = false,
  className = '',
  style = {},
  onProgress = null,
  onReady = null,
  /* ★ إصلاح الخلل: كان فشل النموذج صامتاً (اللودر يدور للأبد). الآن يُبلَّغ */
  onError = null,
}) {
  const mountRef = useRef(null);
  const fxRef = useRef(effects);
  const spinRef = useRef(autoRotate);
  fxRef.current = effects;
  spinRef.current = autoRotate;
  const onErrorRef = useRef(onError);
  onErrorRef.current = onError;

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return;
    let disposed = false;
    function fail(err) {
      if (disposed) return;
      try {
        if (onErrorRef.current) onErrorRef.current(err instanceof Error ? err : new Error(String(err)));
      } catch (e) {}
    }
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const coarse = window.matchMedia('(pointer: coarse)').matches;
    const mobileGuess = () => coarse || mount.clientWidth < 640;
    let isMobile = mobileGuess();

    // ---------- renderer / scene / camera ----------
    /* ★ إصلاح الخلل: إنشاء سياق WebGL قد يرمي (متصفح بلا WebGL أو سياقات
       مستنفدة) — كان يترك اللودر معلّقاً. الآن يُبلَّغ كفشل مع زر إعادة. */
    let renderer = null;
    try {
      renderer = new THREE.WebGLRenderer({
        antialias: !isMobile,
        alpha: true,
        powerPreference: 'high-performance',
      });
    } catch (err) {
      fail(err);
      return undefined;
    }
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.0;
    /* ★ R22: سقف دقة أقل (1.5 بدل 2 للديسكتوب، 1.25 بدل 1.6 للجوال) —
       فرق غير مرئي على شاشة القسم، وتوفير كبير في البكسلات. */
    const DPR = Math.min(window.devicePixelRatio || 1, isMobile ? 1.25 : 1.5);
    renderer.setPixelRatio(DPR);
    renderer.domElement.style.cssText =
      'position:absolute;inset:0;width:100%;height:100%;display:block;opacity:0;transition:opacity .8s;';
    mount.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(30, 1, 0.05, 60);
    const pmrem = new THREE.PMREMGenerator(renderer);
    scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    if ('environmentIntensity' in scene) scene.environmentIntensity = 0.35;
    scene.add(new THREE.AmbientLight(0xfff1d6, 0.3));
    const key = new THREE.DirectionalLight(0xffdca6, 1.7);
    key.position.set(-1.6, 2.6, 2.2);
    scene.add(key);
    const rim = new THREE.DirectionalLight(0xffdfae, 0.4);
    rim.position.set(1.8, 1.2, -1.6);
    scene.add(rim);
    const emberLight = new THREE.PointLight(0xff8033, 0, 1.6, 2.0);
    scene.add(emberLight);

    const framed = { pos: new THREE.Vector3(), look: new THREE.Vector3() };
    function frameCamera() {
      const w = mount.clientWidth || 1;
      const h = mount.clientHeight || 1;
      const aspect = w / h;
      camera.aspect = aspect;
      camera.updateProjectionMatrix();
      const base = new THREE.Vector3(...P.camPos);
      const look = new THREE.Vector3(...P.camLook);
      let k = 1;
      if (aspect < 1) k = 1 + (1 - aspect) * 2.0;
      if (aspect < 0.6) look.y -= 0.03;
      framed.pos.copy(look).addScaledVector(base.sub(look), k);
      framed.look.copy(look);
      camera.position.copy(framed.pos);
      camera.lookAt(framed.look);
    }

    // ---------- procedural textures / meshes ----------
    const smokeTex = softCircleTexture(128, 0.3);
    const sparkTex = softCircleTexture(64, 0.55);
    const product = new THREE.Group();
    scene.add(product);
    let modelRoot = null;
    const tipWorld = new THREE.Vector3();
    const mouthWorld = new THREE.Vector3();

    const discs = (() => {
      const geo = new THREE.CylinderGeometry(0.075, 0.08, 0.036, 28);
      const mat = new THREE.MeshStandardMaterial({
        color: 0x17130f,
        roughness: 0.95,
        metalness: 0.0,
        bumpMap: noiseTexture(),
        bumpScale: 0.6,
      });
      const g = new THREE.Group();
      const a = new THREE.Mesh(geo, mat);
      a.position.set(...P.discA);
      a.rotation.y = 0.4;
      const b = new THREE.Mesh(geo, mat.clone());
      b.position.set(...P.discB);
      b.rotation.y = 2.1;
      // third disc: resting on top of the pair, slight tilt — low edge kisses disc A, no overlap
      const c = new THREE.Mesh(geo, mat.clone());
      c.position.set(0.125, 0.0622, 0.307);
      c.rotation.set(0, 0.45, 0.105);
      g.add(a, b, c);
      return g;
    })();
    product.add(discs);
    const shadow = new THREE.Group();
    const wide = new THREE.Mesh(
      new THREE.PlaneGeometry(1.35, 1.0),
      new THREE.MeshBasicMaterial({
        map: shadowTexture(),
        transparent: true,
        depthWrite: false,
        opacity: 0.9,
      })
    );
    wide.rotation.x = -Math.PI / 2;
    wide.position.set(0.1, 0.0015, 0.1);
    wide.renderOrder = -1;
    const core = new THREE.Mesh(
      new THREE.PlaneGeometry(0.55, 0.42),
      new THREE.MeshBasicMaterial({
        map: shadowTexture(),
        transparent: true,
        depthWrite: false,
        opacity: 0.95,
      })
    );
    core.rotation.x = -Math.PI / 2;
    core.position.set(0.14, 0.003, 0.05);
    core.renderOrder = -2;
    shadow.add(wide, core);
    product.add(shadow);

    // ---------- GPU particles ----------
    const fxGroup = new THREE.Group();
    scene.add(fxGroup);
    const smokeUniformsList = [];
    let pointScale = 1;
    function refreshPointScale() {
      pointScale = renderer.domElement.height / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
      for (const u of smokeUniformsList) if (u.uScale) u.uScale.value = pointScale;
      if (sparksU) sparksU.uScale.value = pointScale;
      if (dustU) dustU.uScale.value = pointScale;
    }
    function makeSmoke({ count, emitter, rise, spread, size0, size1, opacity, tint, duration, drift }) {
      const geo = new THREE.BufferGeometry();
      const pos = new Float32Array(count * 3);
      const seed = new Float32Array(count * 4);
      for (let i = 0; i < count; i++) {
        pos.set([emitter.x, emitter.y, emitter.z], i * 3);
        seed[i * 4] = Math.random();
        seed[i * 4 + 1] = Math.random();
        seed[i * 4 + 2] = Math.random();
        seed[i * 4 + 3] = Math.random();
      }
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      geo.setAttribute('aSeed', new THREE.BufferAttribute(seed, 4));
      const uniforms = {
        uTime: { value: Math.random() * 100 },
        uTex: { value: smokeTex },
        uRise: { value: rise },
        uSpread: { value: spread },
        uSize0: { value: size0 },
        uSize1: { value: size1 },
        uOpacity: { value: opacity },
        uTint: { value: new THREE.Color(...tint) },
        uDuration: { value: duration },
        uDrift: { value: drift },
        uScale: { value: pointScale },
      };
      smokeUniformsList.push(uniforms);
      const mat = new THREE.ShaderMaterial({
        uniforms,
        transparent: true,
        depthWrite: false,
        vertexShader: `
          attribute vec4 aSeed;
          uniform float uTime,uRise,uSpread,uSize0,uSize1,uDuration,uDrift,uScale;
          varying float vAlpha; varying float vShade;
          void main(){
            float t = fract(uTime / uDuration + aSeed.x);
            vec3 p = position;
            float sway = sin(t*6.2831*(0.7+aSeed.y) + aSeed.z*6.2831);
            float sway2 = cos(t*6.2831*(0.5+aSeed.w) + aSeed.y*6.2831);
            p.y += t * uRise;
            p.x += sway * uSpread * t + uDrift * t;
            p.z += sway2 * uSpread * 0.7 * t;
            vec4 mv = modelViewMatrix * vec4(p, 1.0);
            float size = mix(uSize0, uSize1, t);
            gl_PointSize = size * uScale / -mv.z;
            vAlpha = smoothstep(0.0, 0.18, t) * (1.0 - smoothstep(0.55, 1.0, t));
            vShade = 0.75 + 0.25 * aSeed.y;
            gl_Position = projectionMatrix * mv;
          }`,
        fragmentShader: `
          uniform sampler2D uTex; uniform vec3 uTint; uniform float uOpacity;
          varying float vAlpha; varying float vShade;
          void main(){
            float a = texture2D(uTex, gl_PointCoord).a;
            gl_FragColor = vec4(uTint * vShade, a * vAlpha * uOpacity);
          }`,
      });
      const pts = new THREE.Points(geo, mat);
      pts.frustumCulled = false;
      pts.renderOrder = 5;
      return pts;
    }
    let sparksU = null;
    function makeSparks(count, emitter) {
      const geo = new THREE.BufferGeometry();
      const pos = new Float32Array(count * 3);
      const seed = new Float32Array(count * 4);
      for (let i = 0; i < count; i++) {
        pos.set([emitter.x, emitter.y, emitter.z], i * 3);
        seed[i * 4] = Math.random();
        seed[i * 4 + 1] = Math.random() * Math.PI * 2;
        seed[i * 4 + 2] = 0.5 + Math.random();
        seed[i * 4 + 3] = Math.random();
      }
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      geo.setAttribute('aSeed', new THREE.BufferAttribute(seed, 4));
      sparksU = { uTime: { value: 0 }, uTex: { value: sparkTex }, uScale: { value: pointScale } };
      const mat = new THREE.ShaderMaterial({
        uniforms: sparksU,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        vertexShader: `
          attribute vec4 aSeed;
          uniform float uTime, uScale;
          varying float vTw;
          void main(){
            float life = 1.0 + aSeed.x * 1.2;
            float t = fract(uTime / life + aSeed.w);
            vec3 p = position;
            float ang = aSeed.y + uTime * 0.6;
            float r = 0.02 + t * (0.05 + aSeed.z * 0.06);
            p.x += cos(ang) * r * t + t * t * 0.04;
            p.z += sin(ang) * r * t;
            p.y += t * (0.22 + aSeed.z * 0.20) - t * t * 0.28;
            vec4 mv = modelViewMatrix * vec4(p, 1.0);
            float tw = 0.55 + 0.45 * sin(uTime * (14.0 + aSeed.z * 10.0) + aSeed.y * 20.0);
            vTw = tw * (1.0 - t) * (1.0 - t);
            gl_PointSize = (0.008 + aSeed.z * 0.013) * uScale / -mv.z * tw;
            gl_Position = projectionMatrix * mv;
          }`,
        fragmentShader: `
          uniform sampler2D uTex;
          varying float vTw;
          void main(){
            float a = texture2D(uTex, gl_PointCoord).a;
            vec3 col = mix(vec3(1.0,0.45,0.1), vec3(1.0,0.85,0.45), vTw);
            gl_FragColor = vec4(col * 2.2, a * vTw);
          }`,
      });
      const pts = new THREE.Points(geo, mat);
      pts.frustumCulled = false;
      pts.renderOrder = 6;
      return pts;
    }
    let dustU = null;
    function makeDust(count, center) {
      const geo = new THREE.BufferGeometry();
      const pos = new Float32Array(count * 3);
      const seed = new Float32Array(count * 4);
      for (let i = 0; i < count; i++) {
        pos[i * 3] = center.x + (Math.random() - 0.5) * 0.55;
        pos[i * 3 + 1] = center.y + Math.random() * 0.35;
        pos[i * 3 + 2] = center.z + (Math.random() - 0.5) * 0.45;
        seed[i * 4] = Math.random();
        seed[i * 4 + 1] = Math.random();
        seed[i * 4 + 2] = Math.random();
        seed[i * 4 + 3] = Math.random();
      }
      geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      geo.setAttribute('aSeed', new THREE.BufferAttribute(seed, 4));
      dustU = { uTime: { value: Math.random() * 50 }, uTex: { value: smokeTex }, uScale: { value: pointScale } };
      const mat = new THREE.ShaderMaterial({
        uniforms: dustU,
        transparent: true,
        depthWrite: false,
        vertexShader: `
          attribute vec4 aSeed;
          uniform float uTime, uScale;
          varying float vA;
          void main(){
            float span = 4.5 + aSeed.x * 3.5;
            float t = fract(uTime / span + aSeed.y);
            vec3 p = position;
            p.y -= t * 0.26;
            p.x += sin(t*6.2831 + aSeed.z*6.2831) * 0.035;
            p.z += cos(t*5.0 + aSeed.w*6.2831) * 0.03;
            vec4 mv = modelViewMatrix * vec4(p, 1.0);
            gl_PointSize = (0.007 + aSeed.z * 0.010) * uScale / -mv.z;
            vA = smoothstep(0.0,0.18,t) * (1.0 - smoothstep(0.55,1.0,t)) * 0.55;
            gl_Position = projectionMatrix * mv;
          }`,
        fragmentShader: `
          uniform sampler2D uTex;
          varying float vA;
          void main(){
            float a = texture2D(uTex, gl_PointCoord).a;
            gl_FragColor = vec4(vec3(1.0,0.92,0.78), a * vA);
          }`,
      });
      const pts = new THREE.Points(geo, mat);
      pts.frustumCulled = false;
      pts.renderOrder = 4;
      return pts;
    }
    // Realistic flame: teardrop sprite (white-yellow core -> orange -> transparent)
    function makeFlameTexture() {
      const w = 64, h = 96;
      const c = document.createElement('canvas');
      c.width = w; c.height = h;
      const x = c.getContext('2d');
      const blob = (cx, cy, r, stops) => {
        const g = x.createRadialGradient(cx, cy, 0, cx, cy, r);
        for (const [o, col] of stops) g.addColorStop(o, col);
        x.fillStyle = g;
        x.beginPath(); x.arc(cx, cy, r, 0, 7); x.fill();
      };
      blob(w / 2, h * 0.62, h * 0.42, [[0, 'rgba(255,120,20,0.85)'], [0.55, 'rgba(255,90,10,0.35)'], [1, 'rgba(255,60,0,0)']]);
      blob(w / 2, h * 0.66, h * 0.28, [[0, 'rgba(255,200,80,0.95)'], [0.6, 'rgba(255,160,40,0.4)'], [1, 'rgba(255,140,20,0)']]);
      blob(w / 2, h * 0.72, h * 0.15, [[0, 'rgba(255,246,220,1)'], [0.7, 'rgba(255,230,160,0.5)'], [1, 'rgba(255,220,120,0)']]);
      blob(w / 2, h * 0.86, h * 0.10, [[0, 'rgba(255,240,200,0.9)'], [1, 'rgba(255,200,100,0)']]);
      const t = new THREE.CanvasTexture(c);
      t.colorSpace = THREE.SRGBColorSpace;
      return t;
    }
    let flameCore = null, flameOuter = null;
    function makeFlame(anchor) {
      const tex = makeFlameTexture();
      const outer = new THREE.Sprite(new THREE.SpriteMaterial({
        map: tex, color: 0xff8844, transparent: true, opacity: 0.4,
        depthWrite: false, blending: THREE.AdditiveBlending,
      }));
      outer.position.copy(anchor).add(new THREE.Vector3(0, 0.045, 0));
      outer.scale.set(0.12, 0.16, 1);
      outer.renderOrder = 7;
      const core = new THREE.Sprite(new THREE.SpriteMaterial({
        map: tex, color: 0xffd9a0, transparent: true, opacity: 0.9,
        depthWrite: false, blending: THREE.AdditiveBlending,
      }));
      core.position.copy(anchor).add(new THREE.Vector3(0, 0.03, 0));
      core.scale.set(0.07, 0.085, 1);
      core.renderOrder = 8;
      fxGroup.add(outer, core);
      flameOuter = outer; flameCore = core;
    }
    const auraSprites = [];
    function makeAura(center) {
      for (let i = 0; i < 3; i++) {
        const m = new THREE.SpriteMaterial({
          map: smokeTex,
          color: 0xffd9a0,
          transparent: true,
          opacity: 0.05,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
        });
        const s = new THREE.Sprite(m);
        s.position.copy(center).add(new THREE.Vector3(0, 0.12 + i * 0.09, 0));
        s.scale.setScalar(0.55 + i * 0.22);
        s.userData.phase = i * 2.1;
        fxGroup.add(s);
        auraSprites.push(s);
      }
    }

    // ---------- sizing ----------
    function resize() {
      isMobile = mobileGuess();
      const w = mount.clientWidth || 1;
      const h = mount.clientHeight || 1;
      renderer.setSize(w, h, false);
      frameCamera();
      refreshPointScale();
    }

    // ---------- load ----------
    let booted = false;
    const loader = new GLTFLoader();
    loader.load(
      modelUrl,
      (gltf) => {
        if (disposed) return;
        modelRoot = gltf.scene;
        modelRoot.scale.setScalar(P.modelScale);
        modelRoot.rotation.y = P.modelRotY;
        modelRoot.position.set(...P.modelPos);
        modelRoot.traverse((o) => {
          if (o.isMesh) {
            o.material.envMapIntensity = 0.65;
            patchSpoonGold(o.material);
          }
        });
        product.add(modelRoot);
        modelRoot.updateWorldMatrix(true, true);
        tipWorld.set(...P.tipLocal).applyMatrix4(modelRoot.matrixWorld);
        mouthWorld.set(...P.mouthLocal).applyMatrix4(modelRoot.matrixWorld);
        emberLight.position.copy(mouthWorld).add(new THREE.Vector3(0, 0.03, 0));
        /* ★ R22: تخفيف الجسيمات (~35%) — الكثافة البصرية نفسها تقريبًا */
        const nSmoke = isMobile ? 12 : 18;
        fxGroup.add(
          makeSmoke({ count: nSmoke, emitter: mouthWorld, rise: 0.62, spread: 0.035, size0: 0.06, size1: 0.32, opacity: 0.42, tint: [0.78, 0.73, 0.66], duration: 4.2, drift: 0.02 })
        );
        const discC = new THREE.Vector3(
          (P.discA[0] + P.discB[0]) / 2, 0.05, (P.discA[2] + P.discB[2]) / 2
        );
        fxGroup.add(
          makeSmoke({ count: isMobile ? 5 : 7, emitter: discC, rise: 0.35, spread: 0.06, size0: 0.04, size1: 0.2, opacity: 0.1, tint: [0.98, 0.9, 0.72], duration: 6.0, drift: 0.04 })
        );
        fxGroup.add(makeSparks(isMobile ? 25 : 45, mouthWorld));
        fxGroup.add(makeDust(isMobile ? 35 : 60, new THREE.Vector3(0.12, 0.26, 0.3)));
        makeAura(new THREE.Vector3(0.05, 0.05, 0.05));
        makeFlame(mouthWorld);
        refreshPointScale();
        fxGroup.visible = fxRef.current && !reduced;
        booted = true;
        renderer.domElement.style.opacity = '1';
        try {
          let mapInfo = 'none';
          modelRoot.traverse(function (o) {
            if (o.isMesh && o.material && o.material.map && o.material.map.image) {
              mapInfo = o.material.map.image.width + 'x' + o.material.map.image.height;
            }
          });
          if (window.console && window.console.info) window.console.info('[oud-scene] ready, baseMap=' + mapInfo);
        } catch (diagErr) {}
        if (onReady) onReady();
      },
      (ev) => {
        if (onProgress && ev.total) onProgress(Math.round((ev.loaded / ev.total) * 100));
      },
      (err) => {
        /* ★ إصلاح الخلل: كان فشل النموذج (شبكة/رابط) صامتاً — اللودر يدور
           للأبد. الآن يُبلَّغ الغلاف فيعرض زر إعادة المحاولة. */
        fail(err || new Error("تعذّر تحميل نموذج العود"));
      }
    );

    // ---------- loop ----------
    const clock = new THREE.Clock();
    let simT = 0;
    let acc = 0;
    let lowStreak = 0;
    let degraded = false;
    let visible = true;
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
    });
    io.observe(mount);
    const onVis = () => {};
    document.addEventListener('visibilitychange', onVis);
    const onPointer = (e) => {
      if (isMobile || !booted) return;
      const r = mount.getBoundingClientRect();
      const nx = (e.clientX - r.left) / r.width - 0.5;
      const ny = (e.clientY - r.top) / r.height - 0.5;
      camera.position.x += (framed.pos.x + nx * 0.12 - camera.position.x) * 0.04;
      camera.position.y += (framed.pos.y - ny * 0.08 - camera.position.y) * 0.04;
      camera.lookAt(framed.look);
    };
    mount.addEventListener('pointermove', onPointer);
    window.addEventListener('resize', resize);
    resize();

    let raf = 0;
    function tick() {
      raf = requestAnimationFrame(tick);
      if (!visible || document.hidden) return;
      const dt = Math.min(clock.getDelta(), 0.1);
      const fxOn = fxRef.current && !reduced;
      fxGroup.visible = fxOn;
      if (fxOn && booted) {
        simT += dt;
        for (const u of smokeUniformsList) u.uTime.value += dt;
        if (sparksU) sparksU.uTime.value += dt;
        if (dustU) dustU.uTime.value += dt;
        const f = 0.65 + 0.35 * Math.sin(simT * 11.3) * Math.sin(simT * 5.7 + 1.3);
        const fast = 0.75 + 0.25 * Math.sin(simT * 23.7) * Math.sin(simT * 13.3 + 1.7);
        emberLight.intensity = 2.4 * f + 0.9 * fast;
        if (flameCore && flameOuter) {
          const n1 = Math.sin(simT * 23.7) * Math.sin(simT * 13.3 + 1.7);
          const n2 = Math.sin(simT * 31.7 + 0.6) * Math.sin(simT * 17.9);
          flameCore.scale.set(0.07 * (1 + 0.16 * n1), 0.085 * (1 + 0.24 * n2), 1);
          flameCore.material.opacity = 0.68 + 0.24 * n1;
          flameCore.position.x = mouthWorld.x + 0.008 * n2;
          flameCore.position.y = mouthWorld.y + 0.03 + 0.004 * n1;
          flameOuter.scale.set(0.12 * (1 + 0.1 * n2), 0.16 * (1 + 0.15 * n1), 1);
          flameOuter.material.opacity = 0.24 + 0.12 * n2;
        }
        for (let i = 0; i < auraSprites.length; i++) {
          const s = auraSprites[i];
          const b = 1 + 0.12 * Math.sin(simT * 0.7 + s.userData.phase);
          s.scale.setScalar((0.55 + i * 0.22) * b);
          s.material.opacity = 0.045 + 0.02 * Math.sin(simT * 0.9 + s.userData.phase);
        }
      } else {
        emberLight.intensity = 0;
      }
      if (spinRef.current && modelRoot) modelRoot.rotation.y += dt * 0.35;
      renderer.render(scene, camera);
      acc += dt;
      if (acc >= 2 && !degraded && booted && dt > 0) {
        const fps = 1 / dt;
        if (fps < 28) {
          lowStreak++;
          if (lowStreak >= 4) {
            degraded = true;
            renderer.setPixelRatio(1);
            resize();
          }
        } else lowStreak = 0;
        acc = 0;
      }
    }
    tick();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      io.disconnect();
      document.removeEventListener('visibilitychange', onVis);
      mount.removeEventListener('pointermove', onPointer);
      window.removeEventListener('resize', resize);
      scene.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          const mats = Array.isArray(o.material) ? o.material : [o.material];
          mats.forEach((m) => {
            if (m.map) m.map.dispose();
            m.dispose();
          });
        }
      });
      smokeTex.dispose();
      sparkTex.dispose();
      pmrem.dispose();
      renderer.dispose();
      if (renderer.domElement.parentNode === mount) mount.removeChild(renderer.domElement);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [modelUrl]);

  return (
    <div
      className={className}
      style={{ position: 'relative', overflow: 'hidden', background: '#0d0b08', ...style }}
    >
      {backgroundUrl && (
        <img
          src={backgroundUrl}
          alt=""
          draggable={false}
          onError={function (e) { try { e.currentTarget.style.display = "none"; } catch (err) {} }}
          style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center 38%' }}
        />
      )}
      {!backgroundUrl && placeholder && (
        <img
          src={placeholder}
          alt=""
          draggable={false}
          style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', filter: 'blur(20px)', transform: 'scale(1.1)' }}
        />
      )}
      <div
        ref={mountRef}
        style={{ position: 'absolute', inset: 0 }}
      />
      <div
        style={{
          position: 'absolute', inset: 0, pointerEvents: 'none',
          background: 'linear-gradient(to bottom, rgba(10,6,2,.30) 0%, rgba(10,6,2,0) 30%, rgba(10,6,2,0) 70%, rgba(10,6,2,.35) 100%)',
        }}
      />
    </div>
  );
}
